<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\{Database,FreeTables};
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','Test'),('b','Fremd');INSERT INTO actors(id,club_id,role) VALUES('owner','a','members'),('reader','a','member'),('editor','a','editor'),('foreign','b','members')");
$n=0;function ok(bool $v,string $s):void{global $n;if(!$v)throw new RuntimeException($s);$n++;echo "PASS $s\n";}function denied(callable $f,string $s):void{try{$f();}catch(DomainException){ok(true,$s);return;}throw new RuntimeException($s);}
$owner=new FreeTables($db,'owner');$reader=new FreeTables($db,'reader');$editor=new FreeTables($db,'editor');$foreign=new FreeTables($db,'foreign');
denied(fn()=>$reader->create('x',['a'],['text']),'ordinary member cannot create');
$id=$owner->create('Vereinsfest',['Aufgabe','Menge','Bis','Erledigt'],['text','number','date','boolean']);
ok(count($owner->listing())===1,'owner lists new table');ok($reader->listing()===[],'private by default');denied(fn()=>$editor->table($id),'editor has no implicit rights');denied(fn()=>$foreign->table($id),'foreign table denied');
$row=$owner->saveRow($id,'',0,['=unsafe','2','2026-09-05','Nein']);ok(count($owner->rows($id))===1,'row persists');
denied(fn()=>$owner->saveRow($id,$row,1,['x','NaN','2026-09-05','Nein']),'number validation');denied(fn()=>$owner->saveRow($id,$row,1,['x','2','2026-02-30','Nein']),'date validation');
$owner->share($id,'reader','read',1);ok(count($reader->rows($id))===1,'explicit reader works');denied(fn()=>$reader->saveRow($id,$row,1,['x','2','','Ja']),'reader cannot write');
$owner->share($id,'reader','write',2);$reader->saveRow($id,$row,1,['=unsafe','3','','Ja']);denied(fn()=>$owner->saveRow($id,$row,1,['x','2','','Ja']),'concurrent update protected');
ok(str_contains($owner->export($id),"'=unsafe"),'CSV formula escaped');
$owner->share($id,'reader','none',3);denied(fn()=>$reader->export($id),'revocation stops exports');
denied(fn()=>$owner->share($id,'foreign','read',4),'cross-club share denied');
$owner->archive($id,4,true);ok(count($owner->listing(true))===1,'archive retains table');denied(fn()=>$owner->saveRow($id,'',0,['x','2','','Ja']),'archive prevents edits');$owner->archive($id,5,false);ok(count($owner->rows($id))===1,'restore retains rows');
$csv="Aufgabe;Menge;Bis;Erledigt\nImport;4;2026-10-01;Ja\n";$preview=$owner->importPreview($id,$csv);
denied(fn()=>$owner->import($id,$csv.'Geändert;1;;Nein', $preview['hash']),'changed CSV rejected after preview');
ok($owner->import($id,$csv,$preview['hash'])===1,'validated import stored');
ok($owner->import($id,$csv,$preview['hash'])===0,'repeated import deduplicated');
denied(fn()=>$owner->importPreview($id,"Falscher Kopf\nWert\n"),'incompatible CSV header rejected');
$owner->configure($id,'Aufgaben',['Aufgabe','Menge','Bis','Erledigt','Einheit'],['text','number','date','boolean','unit'],6);
ok(count($owner->table($id)['columns'])===5,'column added without data loss');ok($owner->rows($id)[0]['cells'][4]==='','new column starts empty');
denied(fn()=>$owner->configure($id,'Aufgaben',['Aufgabe','Menge','Bis','Erledigt','Einheit'],['date','number','date','boolean','unit'],7),'incompatible type change rejects all changes');
ok($owner->table($id)['columns'][0]['type']==='text','failed conversion rolls back');
$first=$owner->rows($id)[0];$selected=[$first['id'].':'.$first['version']];$bulkKey=bin2hex(random_bytes(16));
ok($owner->bulk($id,$selected,'copy',$bulkKey)===1,'row copied');ok($owner->bulk($id,$selected,'copy',$bulkKey)===0,'row copy retry deduplicated');
$owner->bulk($id,$selected,'archive',bin2hex(random_bytes(16)));$archived=$owner->rows($id,'',true);ok(count($archived)===1,'row archive retains values');$owner->bulk($id,[$archived[0]['id'].':'.$archived[0]['version']],'restore',bin2hex(random_bytes(16)));ok(count($owner->rows($id,'',true))===0,'row restored');
$duplicate=$owner->duplicate($id,'Kopie',bin2hex(random_bytes(16)));ok(count($owner->rows($duplicate))===count($owner->rows($id)),'list copy includes rows');denied(fn()=>$reader->table($duplicate),'copy remains private');
ok(\Kulturhus\Verein\Tests\MySqlFixture::integrity($db)==='ok','integrity');$retryKey=bin2hex(random_bytes(16));$retryValues=array_fill(0,count($owner->table($id)['columns']),'');
$retryRow=$owner->saveRow($id,'',0,$retryValues,$retryKey);ok($owner->saveRow($id,'',0,$retryValues,$retryKey)===$retryRow,'lost create response retries without duplicate row');
$retryValues[0]='Changed after unknown result';denied(fn()=>$owner->saveRow($id,'',0,$retryValues,$retryKey),'ambiguous changed retry requires reloading saved row');
echo "$n free-table checks passed\n";
